import sys, time, unittest, collections
class R(unittest.TextTestResult):
    times = {}
    def startTest(self, t): self._t = time.perf_counter(); super().startTest(t)
    def stopTest(self, t): R.times[t.id()] = time.perf_counter() - self._t; super().stopTest(t)
suite = unittest.defaultTestLoader.discover(".", pattern="test_*.py")
unittest.TextTestRunner(resultclass=R, verbosity=0, stream=open("nul","w")).run(suite)
tot = sum(R.times.values()); print("total %.1fs over %d tests" % (tot, len(R.times)))
by = collections.Counter()
for k, v in R.times.items(): by[".".join(k.split(".")[:2])] += v
for k, v in by.most_common(12): print("%6.1fs  %s" % (v, k))
print("-- slowest tests")
for k, v in sorted(R.times.items(), key=lambda kv: -kv[1])[:12]: print("%6.2fs  %s" % (v, k))
print("tests over 1s: %d, their sum %.1fs" % (sum(v>1 for v in R.times.values()), sum(v for v in R.times.values() if v>1)))
EOF
